"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2962],{6003:e=>{e.exports=JSON.parse('{"functions":[{"name":"nextOpen","desc":"","params":[{"name":"odds","desc":"the box\'s resolved per-rarity odds","lua_type":"{ [string]: number }"},{"name":"pityCount","desc":"opens since the player\'s last Legendary+ pull","lua_type":"number"},{"name":"pityOpens","desc":"the box\'s guarantee window; 0 means none","lua_type":"number"}],"returns":[{"desc":"per-rarity odds of the next open","lua_type":"{ [string]: number }"},{"desc":"true when the next open is the guaranteed one","lua_type":"boolean"}],"function_type":"static","source":{"line":44,"path":"src/Shared/Modules/BoxOdds.luau"}}],"properties":[],"types":[],"name":"BoxOdds","desc":"The tier odds a crate\'s next open rolls with, so the crate window shows\\nexactly what BoxService draws.\\n\\nHard pity: once a player\'s opens since their last Legendary+ pull reach\\n`pityOpens - 1`, the next open is guaranteed Legendary+. BoxService keeps\\na natural Legendary+ roll and re-rolls anything lower across the\\nLegendary+ tiers with odds > 0, weighted by those odds. That open lands\\non each of those tiers with `odds / (sum of their odds)` and on every\\nlower tier with 0. Duplicate protection never moves a tier\'s odds, so\\n[DuplicateProtection.chances] takes the result as is.\\n\\nPure, so the server can roll with the same table.","source":{"line":20,"path":"src/Shared/Modules/BoxOdds.luau"}}')}}]);